const staticData = $getWorkflowStaticData('global');
staticData.seenVideoIds = staticData.seenVideoIds || [];

const items = $input.all().map(i => i.json);
if (!items.length) {
  return [];
}

const targetProfiles = ["diegodoal"];

function parseTime(item) {
  if (item.createTimeISO) {
    const t = Date.parse(item.createTimeISO);
    if (!Number.isNaN(t)) return t;
  }
  const raw = Number(item.createTime);
  if (!Number.isFinite(raw) || raw === 0) return 0;
  return raw < 1e12 ? raw * 1000 : raw;
}

const byAuthor = {};
for (const item of items) {
  const author = (
    item.authorMeta?.name ||
    item.authorMeta?.nickName ||
    item.author ||
    ""
  ).replace('@', '').toLowerCase();

  const matched = targetProfiles.find(t => t.toLowerCase() === author) || author || "unknown";
  const createTime = parseTime(item);

  if (!byAuthor[matched] || createTime > byAuthor[matched].timestamp) {
    byAuthor[matched] = {
      id: String(item.id || item.videoMeta?.id || ""),
      author: matched,
      authorDisplay: item.authorMeta?.name || matched,
      text: item.text || item.caption || item.desc || "No caption",
      webVideoUrl: item.webVideoUrl || `https://www.tiktok.com/@${matched}/video/${item.id}`,
      timestamp: createTime
    };
  }
}

const newVideos = [];
for (const author of Object.keys(byAuthor)) {
  const video = byAuthor[author];
  if (video.id && !staticData.seenVideoIds.includes(video.id)) {
    newVideos.push({ json: video });
  }
}
return newVideos;

const item = $input.item.json;
const caption = String(item.text || 'No caption');
const author = String(item.authorDisplay || item.author || 'unknown');
const prompt = [
  'You are an executive content analyst.',
  `Caption and information from a TikTok video by @${author}:`,
  '',
  `Caption: ${caption}`,
  '',
  'Return ONLY JSON with these keys:',
  '- takeaway: one punchy English sentence with the core message',
  '- topic: 2-4 words',
  '- context: 1-2 sentences of background'
].join('\n');

return [{
  json: {
    id: item.id,
    author: item.author,
    authorDisplay: item.authorDisplay,
    text: item.text,
    webVideoUrl: item.webVideoUrl,
    timestamp: item.timestamp,
    geminiPayload: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { responseMimeType: 'application/json' }
    }
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.seenVideoIds = staticData.seenVideoIds || [];
staticData.feed = staticData.feed || [];

const video = $('Prepare Gemini Request').item.json;
const gemini = $input.item.json;

let summary = { takeaway: 'No summary', topic: '', context: '' };
const raw = gemini.candidates?.[0]?.content?.parts?.[0]?.text;
if (raw) {
  try {
    const parsed = JSON.parse(raw);
    summary = {
      takeaway: parsed.takeaway || summary.takeaway,
      topic: parsed.topic || '',
      context: parsed.context || ''
    };
  } catch (error) {
    summary.takeaway = String(raw);
  }
}

if (video.id && !staticData.seenVideoIds.includes(video.id)) {
  staticData.seenVideoIds.push(video.id);
}
if (staticData.seenVideoIds.length > 200) {
  staticData.seenVideoIds = staticData.seenVideoIds.slice(-200);
}

const entry = {
  id: video.id,
  author: video.authorDisplay,
  url: video.webVideoUrl,
  caption: video.text,
  takeaway: summary.takeaway,
  topic: summary.topic,
  context: summary.context,
  at: new Date().toISOString()
};

staticData.feed.unshift(entry);
staticData.feed = staticData.feed.slice(0, 50);
return [{ json: entry }];

const staticData = $getWorkflowStaticData('global');
const feed = staticData.feed || [];

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function when(iso) {
  try {
    return new Date(iso).toLocaleString('en-GB', { timeZone: 'Europe/Madrid' });
  } catch (error) {
    return iso || '';
  }
}

const cards = feed.length
  ? feed.map((item) => `
      <article class="card">
        <div class="meta">
          <span class="author">@${esc(item.author)}</span>
          ${item.topic ? `<span class="topic">${esc(item.topic)}</span>` : ''}
        </div>
        <h2>${esc(item.takeaway)}</h2>
        ${item.context ? `<p>${esc(item.context)}</p>` : ''}
        <p class="caption">${esc(item.caption)}</p>
        <div class="footer">
          <a href="${esc(item.url)}" target="_blank" rel="noopener">Watch on TikTok</a>
          <time>${esc(when(item.at))}</time>
        </div>
      </article>`).join('')
  : '<p class="empty">No videos analyzed yet. Activate this workflow in n8n, click <b>Test now</b>, then refresh this page.</p>';

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8"/>
  <meta name="viewport" content="width=device-width, initial-scale=1"/>
  <title>TikTok Monitor</title>
  <style>
    :root { color-scheme: dark; }
    body { margin: 0; font-family: ui-sans-serif, system-ui, sans-serif; background: #111; color: #eee; }
    main { max-width: 720px; margin: 0 auto; padding: 32px 20px 64px; }
    h1 { font-size: 1.4rem; font-weight: 650; margin: 0 0 8px; }
    .sub { color: #aaa; margin: 0 0 28px; }
    .card { border: 1px solid #333; border-radius: 12px; padding: 18px 18px 14px; margin-bottom: 14px; background: #1a1a1a; }
    .meta { display: flex; gap: 10px; align-items: center; margin-bottom: 10px; }
    .author { font-weight: 600; }
    .topic { font-size: 0.8rem; color: #111; background: #d6e4ff; padding: 2px 8px; border-radius: 999px; }
    h2 { font-size: 1.05rem; line-height: 1.4; margin: 0 0 8px; font-weight: 600; }
    p { margin: 0 0 8px; color: #ccc; line-height: 1.45; }
    .caption { color: #888; font-size: 0.9rem; }
    .footer { display: flex; justify-content: space-between; gap: 12px; margin-top: 12px; font-size: 0.85rem; }
    a { color: #9cbcff; }
    .empty { color: #aaa; }
  </style>
</head>
<body>
  <main>
    <h1>TikTok Monitor</h1>
    <p class="sub">Latest AI takeaways from tracked creators</p>
    ${cards}
  </main>
</body>
</html>`;

return [{ json: { html } }];
